#include <cstdint>
#include <cstddef>

// Simulating Slice class
class Slice {
 public:
  Slice(const char* d, size_t n) : data_(d), size_(n) {}
  const char* data() const { return data_; }
  size_t size() const { return size_; }
 private:
  const char* data_;
  size_t size_;
};

uint32_t BloomHash(const Slice& key) {
  // Implementation of MurmurHash2 for bloom filter hashing
  const uint32_t m = 0x5bd1e995;
  const int r = 24;

  uint32_t h = 0xbc9f1d34;  // Fixed seed for bloom filter
  const size_t len = key.size();
  const char* data = key.data();

  // Process 4 bytes at a time
  size_t i = 0;
  for (size_t count = len; count >= 4; count -= 4) {
    uint32_t k = static_cast<uint32_t>(data[i]) |
                 (static_cast<uint32_t>(data[i + 1]) << 8) |
                 (static_cast<uint32_t>(data[i + 2]) << 16) |
                 (static_cast<uint32_t>(data[i + 3]) << 24);
    k *= m;
    k ^= k >> r;
    k *= m;
    h *= m;
    h ^= k;
    i += 4;
  }

  // Handle remaining bytes
  switch (len & 3) {
    case 3:
      h ^= static_cast<uint32_t>(data[i + 2]) << 16;
      [[fallthrough]];
    case 2:
      h ^= static_cast<uint32_t>(data[i + 1]) << 8;
      [[fallthrough]];
    case 1:
      h ^= static_cast<uint32_t>(data[i]);
      h *= m;
  }

  // Finalization
  h ^= len;
  h ^= h >> 13;
  h *= m;
  h ^= h >> 15;

  return h;
}

// Test
#include <iostream>
int main() {
  const char* test = "hello";
  Slice s(test, 5);
  uint32_t h = BloomHash(s);
  std::cout << "Hash of 'hello': " << h << std::endl;
  return 0;
}

